import sys

data = sys.stdin.read().split()
n = int(data[0])
lines = [(data[1 + 2 * i], data[2 + 2 * i]) for i in range(n)]
accepted = 0
turned_away = 0
for herald in sorted(set(h for h, _ in lines)):
    door_open = True
    rejected = 0
    for h, v in lines:
        if h != herald:
            continue
        if not door_open:
            turned_away += 1
        elif v == "A":
            accepted += 1
            door_open = False
        else:
            rejected += 1
            if rejected == 4:
                door_open = False
print(accepted, turned_away)
